        if (data.showCtaButton !== undefined)
            updateData.showCtaButton = data.showCtaButton;
        if (data.mobileMenuType !== undefined)
            updateData.mobileMenuType = data.mobileMenuType;
        if (data.activeIndicatorStyle !== undefined)
            updateData.activeIndicatorStyle = data.activeIndicatorStyle;
